var root=UnityEditor.PrefabUtility.LoadPrefabContents("Assets/Prefabs/Character.prefab");
try{
 var rig=root.GetComponent<Character.Control.PaddleCharacterVisual>();float error=0,minGap=100,maxElbowStep=0,maxProjectedExcess=0;
 foreach(float g in new[]{.65f,1f,1.5f})foreach(float reach in new[]{.75f,1.05f,1.975f}){
  UnityEngine.Vector3 lastL=UnityEngine.Vector3.zero,lastR=UnityEngine.Vector3.zero;
  for(int i=0;i<=720;i++){
   var q=UnityEngine.Quaternion.Euler(0,0,i*.5f);rig.body.localScale=UnityEngine.Vector3.one*7.5f*g;rig.tool.localScale=UnityEngine.Vector3.one*g;
   rig.tool.rotation=q;rig.tool.position=rig.body.position+q*new UnityEngine.Vector3(reach*g,.074f*g,0);rig.Pose();
   error=UnityEngine.Mathf.Max(error,rig.HandError);minGap=UnityEngine.Mathf.Min(minGap,UnityEngine.Vector3.Distance(rig.LeftHand,rig.RightHand)/g);
   maxProjectedExcess=UnityEngine.Mathf.Max(maxProjectedExcess,UnityEngine.Vector3.Distance(rig.LeftHand,rig.LeftElbow)-rig.ArmReach*.5f,UnityEngine.Vector3.Distance(rig.RightHand,rig.RightElbow)-rig.ArmReach*.5f);
   if(i>0)maxElbowStep=UnityEngine.Mathf.Max(maxElbowStep,UnityEngine.Vector3.Distance(lastL,rig.LeftElbow)/g,UnityEngine.Vector3.Distance(lastR,rig.RightElbow)/g);
   lastL=rig.LeftElbow;lastR=rig.RightElbow;
  }
 }
 string log="6489 full-circle poses; wrist error="+error+" min grip gap/scale="+minGap+" max elbow displacement per .5deg/scale="+maxElbowStep+" projected limb length excess="+maxProjectedExcess;
 System.IO.File.WriteAllText("scripts/player-natural-grip-20261111/sweep.txt",log);UnityEngine.Debug.Log(log);
 if(error>.001f||minGap<.199f||maxElbowStep>.1f||maxProjectedExcess>.001f)throw new System.Exception("Grip continuity regression");
}finally{UnityEditor.PrefabUtility.UnloadPrefabContents(root);}
